Function: insert(struct node* node, int key)
Path P3: node == NULL → return newNode(key)

```c
void unit_test_insert_null_tree(void) {
    // Setup: no tree exists
    struct node* root = NULL;
    int key = 42;

    // Test: insert into empty tree
    struct node* result = insert(root, key);

    // Assertions
    assert(result != NULL);
    assert(result->key == 42);
    assert(result->left == NULL);
    assert(result->right == NULL);

    // Cleanup
    free(result);
}
```

