void unit_test_buffer_resize_successful_resize(void) {
    // Setup: create a buffer with some content
    buffer_t *buf = helper_create_buffer_with_content("hello");
    size_t new_size = 2000; // not a multiple of 1024, will be rounded up to 2048

    // Test: resize the buffer
    int ret = buffer_resize(buf, new_size);

    // Assertions
    assert(ret == 0);
    assert(buf->len == 2048);
    assert(buf->alloc != NULL);
    assert(buf->data != NULL);
    assert(buf->alloc[2048] == '\0');

    // The original content should still be present at the start
    assert_string_equal(buf->data, "hello");

    // Cleanup
    helper_cleanup_buffer(buf);
}
